"""Adopt predictions regenerated by ``scripts/regen_predictions.py`` into the main results tree (shell).

For each id, compares the rerun's ``folds.csv`` under ``<base>/<id>/`` with the committed ``results/<id>/folds.csv``.
Only if every (seed, fold, metric) score matches within ``--atol`` are its predictions and fold models moved to
``results/<id>/predictions/`` and ``models/<id>/``: predictions must come from the models that produced the
committed scores. A mismatch is reported and nothing is moved for that id. Dry run unless ``--apply``.

    .venv/bin/python scripts/adopt_predictions.py                      # every id under local-runs/regen/, dry run
    .venv/bin/python scripts/adopt_predictions.py --apply
    .venv/bin/python scripts/adopt_predictions.py snli-hyp-only-bow-loglin-8059a0af --apply
"""

import argparse
import shutil
import sys
from pathlib import Path

import pandas as pd

REPO = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(REPO))

from nli.store import models_dir, results_dir  # noqa: E402

KEY = ["seed", "fold", "metric"]


def score_diff(committed: pd.DataFrame, rerun: pd.DataFrame) -> float:
    """Largest absolute score difference; inf if the (seed, fold, metric) rows differ."""
    merged = committed.merge(rerun, on=KEY, how="outer", suffixes=("_committed", "_rerun"), indicator=True)
    if (merged["_merge"] != "both").any():
        return float("inf")
    return float((merged["value_committed"] - merged["value_rerun"]).abs().max())


def move_files(src: Path, dst: Path, apply: bool) -> int:
    files = sorted(p for p in src.iterdir() if p.is_file())
    clashes = [p.name for p in files if (dst / p.name).exists()]
    if clashes:
        raise FileExistsError(f"{dst} already has {clashes[:3]}{'...' if len(clashes) > 3 else ''}")
    if apply:
        dst.mkdir(parents=True, exist_ok=True)
        for p in files:
            shutil.move(str(p), dst / p.name)
    return len(files)


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("ids", nargs="*", help="experiment ids; default: every id under --base")
    parser.add_argument("--base", default=str(REPO / "local-runs" / "regen"), help="parent of the per-id regen roots")
    parser.add_argument("--atol", type=float, default=1e-6, help="max allowed absolute score difference")
    parser.add_argument("--apply", action="store_true", help="move files (default: dry run)")
    args = parser.parse_args()

    base = Path(args.base)
    ids = args.ids or sorted(p.name for p in base.iterdir() if p.is_dir())
    failed = 0
    for eid in ids:
        root = base / eid
        rerun_csv = results_dir(root, eid) / "folds.csv"
        committed_csv = results_dir(REPO, eid) / "folds.csv"
        if not rerun_csv.exists() or not committed_csv.exists():
            print(f"[{eid}] SKIP: missing {'rerun' if not rerun_csv.exists() else 'committed'} folds.csv")
            failed += 1
            continue
        diff = score_diff(pd.read_csv(committed_csv), pd.read_csv(rerun_csv))
        if not diff <= args.atol:
            print(f"[{eid}] MISMATCH: max |score diff| = {diff:.3g} > {args.atol:g}; nothing moved")
            failed += 1
            continue
        verb = "moved" if args.apply else "would move"
        n_pred = move_files(results_dir(root, eid) / "predictions", results_dir(REPO, eid) / "predictions", args.apply)
        n_model = move_files(models_dir(root, eid), models_dir(REPO, eid), args.apply)
        print(f"[{eid}] scores match (max diff {diff:.3g}); {verb} {n_pred} predictions, {n_model} model files")
    return 1 if failed else 0


if __name__ == "__main__":
    sys.exit(main())
